param([string]$TaskRoot,[string]$InstallRoot,[string]$ToolRoot,[string]$EnginePath,[string]$EvidenceRoot,[string]$HarnessPath)
$ErrorActionPreference='Stop'
$TaskRoot=[IO.Path]::GetFullPath($TaskRoot); $InstallRoot=[IO.Path]::GetFullPath($InstallRoot); $ToolRoot=[IO.Path]::GetFullPath($ToolRoot); $EvidenceRoot=[IO.Path]::GetFullPath($EvidenceRoot); $HarnessPath=[IO.Path]::GetFullPath($HarnessPath)
if(-not $InstallRoot.StartsWith($TaskRoot.TrimEnd('\')+'\',[StringComparison]::OrdinalIgnoreCase) -or -not $ToolRoot.StartsWith($TaskRoot.TrimEnd('\')+'\',[StringComparison]::OrdinalIgnoreCase)){throw 'Installed app and tools must remain in the task temp root.'}
if(-not $EvidenceRoot.StartsWith('C:\maos\review-packets\committed-install-gui-validation-2026-10-29',[StringComparison]::OrdinalIgnoreCase)){throw 'Evidence root is outside the current packet.'}
$engineManifest=Get-Content -LiteralPath 'C:\maos\review-packets\install-git-context-correction-2026-10-29\candidate-rust-engine-artifact-manifest.json' -Raw | ConvertFrom-Json
$engineHash=(Get-FileHash -LiteralPath $EnginePath -Algorithm SHA256).Hash.ToLowerInvariant()
if($engineHash -ne $engineManifest.binary.sha256 -or $engineManifest.approved -ne $false){throw 'External engine does not match the recorded unapproved candidate manifest.'}
$node=(Get-Command node.exe -ErrorAction Stop).Source; $appRoot=Join-Path $InstallRoot 'app'; $electron=Join-Path $appRoot 'desktop/node_modules/electron/dist/electron.exe'
if(-not (Test-Path -LiteralPath $electron -PathType Leaf) -or -not (Test-Path -LiteralPath $HarnessPath -PathType Leaf)){throw 'Installed Electron executable or harness is missing.'}
$profile=Join-Path $TaskRoot 'electron host profile with spaces'; $env:APPDATA=Join-Path $profile 'AppData/Roaming'; $env:LOCALAPPDATA=Join-Path $profile 'AppData/Local'; $env:USERPROFILE=$profile; $env:HOME=$profile; $env:TEMP=Join-Path $TaskRoot 'electron temp with spaces'; $env:TMP=$env:TEMP
New-Item -ItemType Directory -Path $env:APPDATA,$env:LOCALAPPDATA,$env:TEMP -Force | Out-Null
$removed=@(Get-ChildItem Env: | Where-Object {$_.Name -match '(?i)(API.?KEY|TOKEN|SECRET|PASSWORD|CREDENTIAL|AUTHORIZATION)' -or $_.Name -match '^GIT_' -or $_.Name -eq 'NODE_OPTIONS' -or $_.Name -eq 'ELECTRON_RUN_AS_NODE'})
foreach($v in $removed){Remove-Item -LiteralPath ('Env:'+ $v.Name) -ErrorAction SilentlyContinue}
$env:NODE_PATH=(Join-Path $appRoot 'desktop/node_modules')+';'+(Join-Path $ToolRoot 'node_modules'); $env:MAOS_TEST_RUST_ENGINE=$EnginePath; $env:GIT_CEILING_DIRECTORIES=$TaskRoot; $env:GIT_CONFIG_NOSYSTEM='true'; $env:GIT_CONFIG_GLOBAL=Join-Path $TaskRoot 'electron empty git config'; Set-Content -LiteralPath $env:GIT_CONFIG_GLOBAL -Value '' -NoNewline -Encoding ascii
$resolved=& $node -e "console.log(JSON.stringify({electron:require('electron'),electronVersion:require('electron/package.json').version,playwright:require('playwright/package.json').version}));" 2>&1; $resolveExit=$LASTEXITCODE; if($resolveExit -ne 0){throw 'Playwright/Electron module resolution failed.'}; $resolvedData=($resolved | Out-String).Trim() | ConvertFrom-Json; if($resolvedData.electron -ne $electron -or $resolvedData.electronVersion -ne '45.0.0' -or $resolvedData.playwright -ne '1.64.1'){throw 'Test harness did not resolve the installed Electron and pinned Playwright.'}
$evidencePath=Join-Path $EvidenceRoot 'electron-installed-journey.json'; $stdout=Join-Path $EvidenceRoot 'electron-installed-journey.stdout.log'; $stderr=Join-Path $EvidenceRoot 'electron-installed-journey.stderr.log'; $working=Join-Path $TaskRoot 'electron rehearsal cwd with spaces'; New-Item -ItemType Directory -Path $working -Force | Out-Null
$args='"'+$HarnessPath+'" --package-root "'+$appRoot+'" --evidence-path "'+$evidencePath+'"'
$started=Get-Date; $proc=Start-Process -FilePath $node -ArgumentList $args -WorkingDirectory $working -NoNewWindow -Wait -PassThru -RedirectStandardOutput $stdout -RedirectStandardError $stderr
$exit=$proc.ExitCode
$report=[ordered]@{timestamp=(Get-Date).ToString('o');command='node <test-only installed Electron rehearsal> --package-root <installed app> --evidence-path <packet>';exitCode=$exit;durationSeconds=[Math]::Round(((Get-Date)-$started).TotalSeconds,1);sourceCommit='27dd1711f47e6278a1b84a6089e900dbe79f1459';bundleSha256='1f333348e92ea988e8fa9ef3be37dd362e69e6d1ab380d3e653f731240b8b61b';installedElectronPath=$electron;installedElectronVersion=$resolvedData.electronVersion;playwrightVersion=$resolvedData.playwright;externalEngineSha256=$engineHash;externalEngineApproved=$false;secretLikeEnvironmentNamesRemoved=$removed.Count;explicitUserDataAndProjectTemp=$true;stdoutPath=$stdout;stderrPath=$stderr;evidencePath=$evidencePath}
$report | ConvertTo-Json -Depth 4 | Set-Content -LiteralPath (Join-Path $EvidenceRoot 'electron-installed-journey-run.json') -Encoding utf8
$report | ConvertTo-Json -Depth 4
if($exit -ne 0){throw "Installed Electron journey exited $exit; inspect the stage in the sanitized runner output."}
